def solve(matrix):
    """Determinant of a square integer matrix via the Bareiss algorithm.

    An empty (0x0) matrix has determinant 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    mat = [list(row) for row in matrix]
    sign = 1
    prev_pivot = 1
    for k in range(n - 1):
        # Find a nonzero pivot in column k at or below row k.
        if mat[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if mat[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            mat[k], mat[swap_row] = mat[swap_row], mat[k]
            sign = -sign
        pivot = mat[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                mat[i][j] = (mat[i][j] * pivot - mat[i][k] * mat[k][j]) // prev_pivot
            mat[i][k] = 0
        prev_pivot = pivot
    return sign * mat[n - 1][n - 1]

def solve(matrix):
    if not matrix:
        return []
    res = []
    top, bottom = 0, len(matrix)-1
    left, right = 0, len(matrix[0])-1
    while top <= bottom and left <= right:
        # top row
        for j in range(left, right+1):
            res.append(matrix[top][j])
        top += 1
        # right column
        for i in range(top, bottom+1):
            res.append(matrix[i][right])
        right -= 1
        if top <= bottom:
            # bottom row
            for j in range(right, left-1, -1):
                res.append(matrix[bottom][j])
            bottom -= 1
        if left <= right:
            # left column
            for i in range(bottom, top-1, -1):
                res.append(matrix[i][left])
            left += 1
    return res

