from fractions import Fraction

def solve(matrix):
    """Exact determinant of a square matrix (integers or floats) as an int."""
    n = len(matrix)
    if n == 0:
        return 1
    if all(len(row) == 0 for row in matrix):
        return 1
    mat = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for k in range(n):
        pivot_row = None
        for i in range(k, n):
            if mat[i][k] != 0:
                pivot_row = i
                break
        if pivot_row is None:
            return 0
        if pivot_row != k:
            mat[k], mat[pivot_row] = mat[pivot_row], mat[k]
            det = -det
        p = mat[k][k]
        det *= p
        for i in range(k + 1, n):
            f = mat[i][k] / p
            row_i, row_k = mat[i], mat[k]
            for j in range(k + 1, n):
                row_i[j] -= f * row_k[j]
            row_i[k] = Fraction(0)
    if det.denominator == 1:
        return int(det)
    return det

