def solve(coins, amount):
    """Fewest coins summing to amount (unlimited supply of each value),
    or -1 if impossible."""
    if amount == 0:
        return 0
    INF = amount + 1
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
