def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    If division by zero occurs, returns 0 (defensive).
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # '/'
                if b == 0:
                    return 0
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0
